    B.Map_qTMNG = new A.ConstantStringMap(B.Object_UBD, ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m", "n", "o", "p", "q", "r", "s", "t", "u", "v", "w", "x", "y", "z", "1", "2", "3", "4", "5", "6", "7", "8", "9", "0", "-", "=", "[", "]", "\\", ";", "'", "`", ",", ".", "/"], type$.ConstantStringMap_String_String);
    B.C_AutocompletePreviousOptionIntent = new A.AutocompletePreviousOptionIntent();
    B.C_AutocompleteNextOptionIntent = new A.AutocompleteNextOptionIntent();
    B.C_AutocompletePreviousPageOptionIntent = new A.AutocompletePreviousPageOptionIntent();
    B.C_AutocompleteNextPageOptionIntent = new A.AutocompleteNextPageOptionIntent();
    B.Map_rLmzr = new A.GeneralConstantMap([B.SingleActivator_uUl4, B.C_AutocompletePreviousOptionIntent, B.SingleActivator_uUl5, B.C_AutocompleteNextOptionIntent, B.SingleActivator_IgW, B.C_AutocompletePreviousPageOptionIntent, B.SingleActivator_uUl, B.C_AutocompleteNextPageOptionIntent], type$.GeneralConstantMap_ShortcutActivator_Intent);
    B.GuideSection_46U = new A.GuideSection("Bodenrouten", "Im Bereich Bodenrouten w\xe4hlst du ausdr\xfccklich \u201eZu Fu\xdf\u201c oder \u201eVelo\u201c. Nach deiner Zustimmung werden Start und Ziel an die dazu passenden FOSSGIS-/OSRM-Profile gesendet. Berechnete und importierte Routen bleiben als eigene lokale Datens\xe4tze auch ohne Netz verf\xfcgbar und werden mit dem pers\xf6nlichen Backup gesichert. GPX erh\xe4lt den Aktivit\xe4tsmodus und vorhandene Quellenh\xf6hen, ohne daraus AGL-H\xf6hen zu erzeugen. Unbekannte GPX-Typen ben\xf6tigen den gew\xe4hlten Importmodus; zus\xe4tzliche oder nicht unterst\xfctzte Angaben werden gemeldet. Ein gespeicherter Linienverlauf best\xe4tigt keine aktuelle \xd6ffnung. Der Bereich bietet Planung und Austausch; die bisherige Autonavigation ist eigenst\xe4ndig.");
    B.GuideSection_4iK = new A.GuideSection("Amtliche Wegenetze", "Wander-, Velo-, Mountainbike- und Winterrouten sind ver\xf6ffentlichte Netze. Legenden erkl\xe4ren die jeweiligen Kategorien; ohne entsprechende Quelldaten wird keine Schwierigkeit berechnet. Diese Online-Kartenebenen sind von deinen gespeicherten Boden- und Flugrouten getrennt. Kartenstand, \xd6ffnung und aktuelle Bedingungen sind eigenst\xe4ndig zu pr\xfcfen.");
    B.GuideSection_lJC = new A.GuideSection("Natur und Sperrungen", "Wildruhezonen k\xf6nnen rechtsverbindlich oder empfohlen sein. Schutzzeiten, \xf6rtliche Bestimmungen und zul\xe4ssige Wege stehen in den offiziellen Details. Der r\xe4umliche Detailabruf ist ein begrenzter Auszug; fehlende kantonale Informationen oder fehlende Treffer best\xe4tigen keine Zug\xe4nglichkeit. Sperrungen und Umleitungen haben eigene G\xfcltigkeitsangaben. Eine Schutzfl\xe4che ist keine pauschale luftrechtliche Einstufung.");
    B.GuideSection_zrr = new A.GuideSection("Gemessene Werte", "MeteoSwiss-Stationswerte sind Messungen an einem einzelnen Standort; Wind und B\xf6en stehen im Quellenformat km/h, Niederschlag als Summe \xfcber zehn Minuten. Die Messzeiten sind UTC und werden zus\xe4tzlich lokal angezeigt. Sie beschreiben kein vollst\xe4ndiges Windfeld und \xe4ndern den Simulatorwind nicht. Fehlende Qualit\xe4tsflags bleiben unbekannt.");
    B.GuideSection_6PV = new A.GuideSection("Gew\xe4sser und Aktualit\xe4t", "BAFU-Live-Werte sind unkorrigiert. 10-Minuten-Mittel enthalten die bereitgestellte Einheit und den verf\xfcgbaren Freigabestatus; unbekannte Referenzen bleiben unbekannt. Frische des lokalen Snapshots und Alter einer einzelnen Messung sind getrennte Angaben. Beobachtungen bewerten weder eine Aktivit\xe4t als sicher noch ersetzen sie amtliche Warnungen. Abrufe erfolgen bewusst, in begrenzten Abst\xe4nden; lokale Messwert-Snapshots lassen sich auch ohne Netz \xf6ffnen.");
    B.List_Grf = makeConstList([B.GuideSection_46U, B.GuideSection_4iK, B.GuideSection_lJC, B.GuideSection_zrr, B.GuideSection_6PV], type$.JSArray_GuideSection);
    B.GuideArticle_L6f = new A.GuideArticle("Outdoor-Karten und Messstationen", B.List_Grf);
    B.GuideSection_iP8 = new A.GuideSection("Starten und anpassen", "\xdcber \u201eProfil w\xe4hlen\u201c oder Einstellungen \u2192 Aktivit\xe4tsprofile w\xe4hlst du eine Vorlage, erstellst ein leeres Profil oder \xfcberspringst die Auswahl. Vorlagen lassen sich bearbeiten, duplizieren und l\xf6schen. Bevorzugte Werkzeuge stehen im Men\xfc zuerst; die Kartenaktionen folgen deinen Schnellaktionen. \u201eAlle Werkzeuge\u201c \xf6ffnet jederzeit den vollst\xe4ndigen Funktionsumfang. Flugrouten und Ausr\xfcstung behalten ihre Bedeutung. Den Fu\xdf- oder Velomodus w\xe4hlst du im Bereich Bodenrouten; ein Aktivit\xe4tsprofil \xe4ndert den Routingmodus nicht automatisch.");
    B.GuideSection_S4L = new A.GuideSection("Karte und laufende Aktivit\xe4ten", "Kartenstartwerte gelten beim App-Start, Aktivieren oder Speichern des aktiven Profils. Sp\xe4tere \xc4nderungen auf der Karte bleiben bis zur n\xe4chsten Aktivierung oder zum Neustart erhalten. W\xe4hrend Bodenansicht, Simulation, Navigation oder pausiertem Renderer werden Startwerte zur\xfcckgestellt und erst danach angewendet. Kamera, Auswahl, laufende Steuerung, Formulare und pers\xf6nliche Datens\xe4tze werden beim Wechsel nicht zur\xfcckgesetzt. Ohne Profil bleibt die aktuelle Karte erhalten.");
    B.GuideSection_o5x = new A.GuideSection("Ebenen und Datenschutz", "Bevorzugte Ebenen sind Schnellzugriffe zu den bestehenden Ebenenreglern. Ein Profil aktiviert keine Datenquelle, Standortfreigabe, API-Verbindung oder automatische Aktualisierung. Quelleneinstellungen und Berechtigungen bleiben eigenst\xe4ndig. Profile speichern keine Zugangsdaten oder pers\xf6nlichen Orte.");
    B.GuideSection_WWU = new A.GuideSection("Sichern und teilen", "Profile und Auswahl sind Bestandteil pers\xf6nlicher Backups. Einzelne Profile k\xf6nnen als versionierte .fpvprofile-Datei exportiert werden. Der Import zeigt eine Vorschau und erg\xe4nzt ein inaktives Profil, ohne vorhandene Profile zu \xfcberschreiben. Unterst\xfctzt werden h\xf6chstens 32 Profile und Dateien bis 128 KiB.");
    B.List_cPP = makeConstList([B.GuideSection_iP8, B.GuideSection_S4L, B.GuideSection_o5x, B.GuideSection_WWU], type$.JSArray_GuideSection);
    B.GuideArticle_7Mc = new A.GuideArticle("Aktivit\xe4tsprofile und Arbeitsbereiche", B.List_cPP);
    B.GuideSection_8sE = new A.GuideSection("Orientierung", "Der Kompass richtet die Karte nach Norden aus. \u201eMein Standort\u201c ortet erst nach Antippen. Langes Dr\xfccken \xf6ffnet Genauigkeit und Verfolgung; Kartenbewegungen beenden die Verfolgung. Die Suche akzeptiert Koordinaten, Orte und Stra\xdfen.");
    B.GuideSection_Njd = new A.GuideSection("Ebenen", "Satellit, Topo und Relief sind Hintergrundkarten. Stra\xdfen und Beschriftungen sind unabh\xe4ngig zuschaltbar. Beschriftungen zeigen eine begrenzte, nach Bildschirmplatz ausgew\xe4hlte Menge offizieller Schweizer Orts- und Stra\xdfennamen. Stra\xdfennamen aus dem amtlichen Verzeichnis erfassen vor allem Stra\xdfen mit Geb\xe4udeadressen; nicht alle Wege und Autobahnen sind enthalten.");
    B.GuideSection_AKK = new A.GuideSection("3D und Quellen", "Geb\xe4ude werden aus Quelldaten gestreamt; Vegetation ist modelliert. Fehlende Objekte werden nicht erg\xe4nzt. Diese Darstellungen haben kein Kollisionsmodell. Eine Routen- oder Flugzeit \xfcberschreibt die Kartenbeleuchtung vor\xfcbergehend. Streaming-Modelle und Beschriftungen sind kein Bestandteil eines vorbereiteten Offline-Kartenpakets.");
    B.List_g29 = makeConstList([B.GuideSection_8sE, B.GuideSection_Njd, B.GuideSection_AKK], type$.JSArray_GuideSection);
    B.GuideArticle_ryl = new A.GuideArticle("Karte und Beschriftungen", B.List_g29);
    B.GuideSection_XOc = new A.GuideSection("Sticks", "Angle/Acro: links Gas und Yaw, rechts Pitch und Roll. GPS: links Bewegung, rechts Blickrichtung, separate Kn\xf6pfe f\xfcr Steigen/Sinken. Beide Touch-Sticks sitzen fest. Die Schnelleinstellungen k\xf6nnen sie ausblenden; Tastatur und externe Controller bleiben nutzbar.");
    B.GuideSection_PPn = new A.GuideSection("Tastatur und Funke", "Angle/Acro: E/Q Gas, A/D Yaw, W/S Pitch, Pfeile links/rechts Roll; IJKL steuert ebenfalls die Lage. GPS/Ego: WASD/Pfeile bewegen, Ziehen oder IJKL umsehen; GPS nutzt E/Q f\xfcr die H\xf6he. Escape beendet die Ansicht. F\xfcr Controller nach Fokusverlust oder echter Trennung die passende Ruheposition einnehmen. Gas-Nullpunkt und Kanalzuordnung bleiben eigene Controller-Einstellungen.");
    B.GuideSection_RM4 = new A.GuideSection("Grenzen", "Angle stabilisiert die Lage, Acro gibt Drehraten vor, GPS bremst und h\xe4lt die H\xf6he. Die Physik ist eine N\xe4herung. Gel\xe4nde-Kontakt ersetzt keine Hinderniskollisionen; Kabel, Geb\xe4ude und B\xe4ume sind keine vollst\xe4ndige Kollisionswelt. Einstellungen au\xdferhalb eines aktiven Fluges gelten f\xfcr die n\xe4chste Simulation.");
    B.List_WSP = makeConstList([B.GuideSection_XOc, B.GuideSection_PPn, B.GuideSection_RM4], type$.JSArray_GuideSection);
    B.GuideArticle_QwO = new A.GuideArticle("Steuerung und Simulation", B.List_WSP);
    B.GuideSection_MpF = new A.GuideSection("Eingabe", "WGS84: Breite, L\xe4nge in Dezimalgrad, z. B. 46.7, 8.4. LV95: Ost / Nord, z. B. 2600000 / 1200000. Die lokale LV95-Umrechnung ist eine N\xe4herung f\xfcr Orientierung, keine Vermessung. Eine Orts- oder Adresssuche ben\xf6tigt dagegen eine Verbindung.");
    B.GuideSection_7tU = new A.GuideSection("H\xf6henbezug", "WGS84-Ellipsoid, Schweizer LN02 und H\xf6he \xfcber Gel\xe4nde (AGL) sind unterschiedliche Bez\xfcge. AGL bezieht sich auf das Gel\xe4nde am jeweiligen Punkt, die Starth\xf6he auf den Startpunkt. Unbekannte Quellenbez\xfcge bleiben unbekannt. Ein flacher Ersatzglobe liefert keine gemessene Gel\xe4ndeh\xf6he.");
    B.List_bxm = makeConstList([B.GuideSection_MpF, B.GuideSection_7tU], type$.JSArray_GuideSection);
    B.GuideArticle_jMT = new A.GuideArticle("Koordinaten und H\xf6hen", B.List_bxm);
    B.GuideSection_IvG = new A.GuideSection("Alle Zonen pr\xfcfen", "Eine UAS-Zone ist nicht automatisch ein vollst\xe4ndiges Flugverbot. Pr\xfcfe jede \xfcberlappende Einschr\xe4nkung, zust\xe4ndige Stelle, Zeit, H\xf6he und Freigabeanforderung. Farben beschreiben unterst\xfctzte Quellattribute; Blau ist keine Flugfreigabe. R\xe4umliche Checks pr\xfcfen Geometrie und ersetzen keine rechtliche Beurteilung.");
    B.GuideSection_Zts = new A.GuideSection("Vor dem Start", "Aktuelle BAZL-Karte, DABS und Original-NOTAM f\xfcr Flugzeit und Route sowie \xf6rtliche Regeln pr\xfcfen. DABS ist ein periodisches Bulletin; NOTAM k\xf6nnen sich zwischen Ausgaben \xe4ndern. Der automatische DABS/NOTAM-Abruf ist derzeit nicht angeschlossen. Auch Wetter, Hindernisse und H\xf6henbez\xfcge pr\xfcfen und unmittelbar vor Abflug erneut verifizieren.");
    B.List_PHH = makeConstList([B.GuideSection_IvG, B.GuideSection_Zts], type$.JSArray_GuideSection);
    B.GuideArticle_gGO = new A.GuideArticle("Luftraum und Flugvorbereitung", B.List_PHH);
    B.GuideSection_m5Q = new A.GuideSection("Zeitangaben", "Abrufzeit ist nicht Ver\xf6ffentlichungszeit. G\xfcltig von/bis beschreibt den angegebenen Zeitraum; ein frischer Download beweist nicht, dass der gesamte Inhalt aktuell ist. Fehlende Zeitangaben werden nicht erg\xe4nzt.");
    B.GuideSection_SS8 = new A.GuideSection("Zust\xe4nde", "Fresh: innerhalb der Abrufrichtlinie. Stale/expired: veraltet oder abgelaufen. Unavailable: kein nutzbarer Datenstand. Refresh failed: die Aktualisierung schlug fehl; ein vorheriger Stand kann noch angezeigt werden. Quellenstatus und Warnungen stehen weiterhin beim jeweiligen Werkzeug. Keine Anzeige garantiert einen sicheren oder erlaubten Flug.");
    B.List_cSj = makeConstList([B.GuideSection_m5Q, B.GuideSection_SS8], type$.JSArray_GuideSection);
    B.GuideArticle_9W2 = new A.GuideArticle("Datenstand und Verf\xfcgbarkeit", B.List_cSj);
    B.GuideSection_vO7 = new A.GuideSection("Bereiche vorbereiten", "Mittelpunkt auf dem Globe w\xe4hlen oder Koordinaten eingeben, Radius bis 25 km und gew\xfcnschte Details/Assets w\xe4hlen. Web bietet zus\xe4tzlich die gesamte Schweiz. Download und Aufbereitung ben\xf6tigen Zeit, freien Speicher und eine ge\xf6ffnete App. Quelll\xfccken und gew\xe4hlte Details begrenzen die Abdeckung.");
    B.GuideSection_m7V = new A.GuideSection("Was fehlt", "Vorbereitete Karten und Gel\xe4nde ersetzen keine Liveinformationen. UAS-, Hindernis- und SLF-Snapshots behalten ihre Quelldaten und G\xfcltigkeit. WMS, Orts-/Stra\xdfenbeschriftungen, Streaming-3D und Liveverkehr/Wetter sind nicht als vollst\xe4ndige Offlineebenen enthalten. Fehlende Beschriftungen f\xfchren im Nur-Cache-Modus nicht zu einem heimlichen Onlineabruf.");
    B.GuideSection_fPX = new A.GuideSection("Pers\xf6nliche Daten", "Backups sch\xfctzen Spots, Bilder, Ausr\xfcstung und Planung unabh\xe4ngig vom Kartencache. Optionales Passwort sch\xfctzt den Export; ungesch\xfctzte Backups sind lesbar. API-Schl\xfcssel und \xf6ffentliche Karten-/OSINT-Caches geh\xf6ren nicht zum pers\xf6nlichen Backup. Browser k\xf6nnen lokalen Speicher l\xf6schen; wichtige Daten zus\xe4tzlich sichern.");
    B.List_HFk = makeConstList([B.GuideSection_vO7, B.GuideSection_m7V, B.GuideSection_fPX], type$.JSArray_GuideSection);
    B.GuideArticle_tAY = new A.GuideArticle("Offline-Karten und Backups", B.List_HFk);
    B.GuideSection_7h5 = new A.GuideSection("Lokal und online", "Pers\xf6nliche Eintr\xe4ge bleiben lokal. Kartenanbieter sehen angeforderte Kartenausschnitte; aktivierte Beschriftungen senden ebenfalls nur den ben\xf6tigten Bereich. Eine best\xe4tigte Route sendet Start/Ziel an den Routingdienst. Orts-/Adresssuchen werden erst beim Absenden \xfcbertragen. Standortanzeige ist freiwillig und arbeitet nur im Vordergrund; es wird kein Standortverlauf angelegt.");
    B.GuideSection_TpA = new A.GuideSection("Zug\xe4nge", "Anbieterbedingungen und Berechtigungen gelten pro Quelle. F\xfcr ASTRA das Token des passenden Produkts verwenden, nicht Token-Hash oder OJP-Token. Android nutzt die bestehende sichere Schl\xfcsselablage; Schl\xfcssel geh\xf6ren weder in einfache Einstellungen noch in Backups. Web-Zug\xe4nge bleiben in den bisher unterst\xfctzten Grenzen. Keine \xf6ffentlichen Proxys geben private Schl\xfcssel weiter.");
    B.List_VLG = makeConstList([B.GuideSection_7h5, B.GuideSection_TpA], type$.JSArray_GuideSection);
    B.GuideArticle_mlu = new A.GuideArticle("Datenschutz und API-Zug\xe4nge", B.List_VLG);
    B.GuideSection_PuT = new A.GuideSection("Wetterraster", "Bew\xf6lkung, Niederschlag, Regen, Neuschnee, Schneeh\xf6he und Temperatur sind getrennte Modellprognosen mit gemeinsamer Zeit. Summen gelten f\xfcr eine Stunde; Schneeh\xf6he ist davon unabh\xe4ngig. Das Stichprobenraster ist kein Wetterradar und keine gemessene 3D-Wolke. Offizielle Radarprodukte ben\xf6tigen eine gesonderte HDF5-/Projektionsaufbereitung und werden hier noch nicht angezeigt.");
    B.GuideSection_7Ga = new A.GuideSection("Modell und Messung", "Eine Modellprognose ist keine lokale Windmessung am Flugpunkt. Die 3D-Pfeile folgen der Luftstr\xf6mung, nicht der meteorologischen Herkunftsrichtung. Farben: gr\xfcn <3, gelb 3\u20137, orange 7\u201312, rot ab 12 m/s. Fehlende oder abgelaufene Werte bleiben nicht verf\xfcgbar.");
    B.GuideSection_rvc = new A.GuideSection("Simulation", "Pfeile und Einfluss auf die Flugphysik sind unabh\xe4ngig schaltbar. Eine feste Sonnen-/Mondzeit \xe4ndert die Winddaten nicht. F\xfcr eine andere Windprognose die Datenquelle/Zeit ausdr\xfccklich w\xe4hlen. Lokale B\xf6en und Gel\xe4nde-Effekte k\xf6nnen von der Modelln\xe4herung abweichen.");
    B.List_HI7 = makeConstList([B.GuideSection_PuT, B.GuideSection_7Ga, B.GuideSection_rvc], type$.JSArray_GuideSection);
    B.GuideArticle_B52 = new A.GuideArticle("Wetter und 3D-Wind", B.List_HI7);
    B.GuideSection_VKC = new A.GuideSection("Ver\xf6ffentlichte Hindernisse", "BAZL-WMS zeigt kombinierte Rasterbilder; Kategorien und H\xf6hen sind daraus nicht einzeln ausw\xe4hlbar. Vektordaten bieten Details, soweit die Quelle sie enth\xe4lt. Unbekannte H\xf6hen bleiben unbekannt. Gerade Kabelverbindungen und einfache Mast-/Kranmodelle sind N\xe4herungen, keine exakte Bauwerksaufnahme.");
    B.GuideSection_9nm = new A.GuideSection("Planungshilfen", "Markierte Puffer um ver\xf6ffentlichte Punkte/Linien sind Planungshilfen. Sie definieren weder rechtlichen Abstand noch vertikale Freig\xe4ngigkeit. Funk-LOS/Fresnel pr\xfcft unterst\xfctzte Gel\xe4ndedaten und Annahmen; Geb\xe4ude, Vegetation und nicht erfasste Objekte k\xf6nnen weiterhin abschatten. Fehlende Hindernisse oder freie Geometrie sind kein Sicherheitsnachweis.");
    B.List_lco = makeConstList([B.GuideSection_VKC, B.GuideSection_9nm], type$.JSArray_GuideSection);
    B.GuideArticle_BLm = new A.GuideArticle("Hindernisse und Funkabschattung", B.List_lco);
    B.GuideSection_BHY = new A.GuideSection("3D-Umgebung", "Unter Einstellungen \u2192 Navigation oder Kartendarstellung \u2192 3D-Umgebung lassen sich Geb\xe4ude und Vegetation jeweils auf Wie Karte, Aus oder Ein stellen. Die normale Karte und Luftfahrthindernisse behalten eigene Einstellungen. Fehlende Streaming-Daten unterbrechen die Navigation nicht. Die gegl\xe4ttete Anzeige bleibt beim letzten GPS-Punkt stehen; Geschwindigkeit und Routenf\xfchrung verwenden die urspr\xfcnglichen Messwerte.");
    B.GuideSection_CcX = new A.GuideSection("Navigation", "Routen und Ansagen sind Orientierungshilfen. Stra\xdfenregeln und die reale Situation gehen vor. Der Kompass richtet zuerst nach Norden aus; erneutes Antippen kehrt zur schr\xe4gen Verfolgungsansicht zur\xfcck. Ungenaue GPS-Signale begrenzen Richtung und Neuberechnung.");
    B.GuideSection_Edl = new A.GuideSection("Verkehrsdaten", "Situationsmeldungen und Messstellen sind verschiedene Quellen mit eigenen Tokens. TMC-Codes ben\xf6tigen die passende amtliche Ortstabelle. Unverortete, abgelaufene oder unvollst\xe4ndige Meldungen d\xfcrfen nicht als freie Strecke gelten. Messgeschwindigkeiten sind punktuelle Beobachtungen, keine fl\xe4chendeckende Live-Staukarte.");
    B.List_xwH = makeConstList([B.GuideSection_BHY, B.GuideSection_CcX, B.GuideSection_Edl], type$.JSArray_GuideSection);
    B.GuideArticle_h63 = new A.GuideArticle("Navigation und Verkehr", B.List_xwH);
    B.Map_tLWF3 = new A.GeneralConstantMap([B.GuideTopic_0, B.GuideArticle_L6f, B.GuideTopic_1, B.GuideArticle_7Mc, B.GuideTopic_2, B.GuideArticle_ryl, B.GuideTopic_3, B.GuideArticle_QwO, B.GuideTopic_4, B.GuideArticle_jMT, B.GuideTopic_5, B.GuideArticle_gGO, B.GuideTopic_6, B.GuideArticle_9W2, B.GuideTopic_7, B.GuideArticle_tAY, B.GuideTopic_8, B.GuideArticle_mlu, B.GuideTopic_9, B.GuideArticle_B52, B.GuideTopic_10, B.GuideArticle_BLm, B.GuideTopic_11, B.GuideArticle_h63], A.findType("GeneralConstantMap<GuideTopic,GuideArticle>"));
    B.Object_Ri3 = {"zh-Hant": 0, "zh-TW": 1, "zh-MO": 2, "zh-HK": 3, ja: 4, ko: 5, zh: 6, "zh-Hans": 7, "zh-CN": 8};
    B.List_Q7q = makeConstList(["Noto Sans TC"], type$.JSArray_String);
    B.List_WVs = makeConstList(["Noto Sans HK", "Noto Sans TC"], type$.JSArray_String);
    B.List_5Jy = makeConstList(["Noto Sans JP"], type$.JSArray_String);
    B.List_2n5 = makeConstList(["Noto Sans KR"], type$.JSArray_String);
    B.List_Q7q0 = makeConstList(["Noto Sans SC"], type$.JSArray_String);
    B.List_wZ1 = makeConstList(["Noto Sans SC", "Noto Sans TC"], type$.JSArray_String);
